const input = $json;
const required = ['contact_id','email','install_type','requested_services','currency'];
for (const f of required) {
    if (!input[f] || String(input[f]).trim()==='') {
        return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'missing:'+f}}];
    }
}
const emailRe = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
if (!emailRe.test(input.email)) {
    return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'email_missing_or_malformed'}}];
}
if (input.currency !== 'GBP') {
    return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'currency_not_gbp'}}];
}
let quantity = null;
if (input.quantity !== undefined && input.quantity !== null && String(input.quantity).trim()!=='') {
    const s = String(input.quantity).trim();
    if (!/^[1-9][0-9]{0,2}$/.test(s)) {
        return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'quantity_malformed'}}];
    }
    quantity = parseInt(s,10);
    if (quantity > 1) {
        return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'quantity_above_max_tbd'}}];
    }
}
const keys = input.requested_services.split(',').map(s=>s.trim()).filter(Boolean);
const ck = require('crypto').createHash('sha256').update([input.contact_id,[...keys].sort().join('+'),new Date().toISOString().split('T')[0]].join('|')).digest('hex');
if (!/^[0-9a-f]{64}$/.test(ck)) {
    return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'idempotency_key_invalid'}}];
}
return [{json:{...input,quantity,keys,idempotency_key:ck,ok:true}}];

const CATALOG = $('Load Catalog').item.json.CATALOG;
const input = $('Validate Input').item.json;
const keys = input.keys || input.requested_services.split(',').map(s=>s.trim()).filter(Boolean);
const installType = input.install_type;
const quantity = input.quantity || null;
const matched = keys.map(k => CATALOG.services.find(s => s.key === k && s.active === true));
if (matched.some(m => m === undefined)) {
  const u = keys.filter(k => !CATALOG.services.some(s => s.key === k && s.active));
  return [{json:{ok:false,needs_human:true,status:'no_matching_service',failure_reason:'no_matching_catalog_service:'+u.join(',')}}];
}
const lines = [];
for (const row of matched) {
  if (row.install_type !== 'both' && row.install_type !== installType) {
    return [{json:{ok:false,needs_human:true,status:'no_matching_service',failure_reason:'service_install_type_mismatch:'+row.key}}];
  }
  if (row.pricing_model === 'per_watt') {
    if (row.unit_size_unit !== 'W') return [{json:{ok:false,needs_human:true,status:'blocked_tbd',failure_reason:'catalog_unit_size_unit_tbd:'+row.key}}];
    if (!/^[1-9][0-9]{1,4}$/.test(String(row.unit_size))) return [{json:{ok:false,needs_human:true,status:'blocked_tbd',failure_reason:'catalog_unit_size_invalid:'+row.key}}];
  }
  const mr = /^\d{1,9}(\.\d{1,2})?$/;
  if (!mr.test(String(row.unit_price))) {
    return [{json:{ok:false,needs_human:true,status:'blocked_tbd',failure_reason:'catalog_price_tbd:'+row.key}}];
  }
  if (row.customer_facing !== true) {
    return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'service_not_customer_facing:'+row.key}}];
  }
  if (!['yes','no','TBD'].includes(row.vat_included)) {
    return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'catalog_vat_invalid:'+row.key}}];
  }
  if (row.vat_included === 'TBD') {
    return [{json:{ok:false,needs_human:true,status:'blocked_tbd',failure_reason:'catalog_vat_tbd:'+row.key}}];
  }
  const price = parseFloat(row.unit_price);
  let minor;
  switch(row.pricing_model) {
    case 'flat': minor = Math.round(price*100); break;
    case 'per_unit': if(quantity===null||quantity===0) return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'quantity_required_for:'+row.key}}]; minor = Math.round(price*quantity*100); break;
    case 'per_watt': if(quantity===null||quantity===0) return [{json:{ok:false,needs_human:true,status:'bad_input',failure_reason:'quantity_required_for:'+row.key}}]; minor = Math.round(price*parseInt(String(row.unit_size),10)*quantity*100); break;
    default: return [{json:{ok:false,needs_human:true,status:'blocked_tbd',failure_reason:'pricing_model_tbd:'+row.key}}];
  }
  lines.push({key:row.key,display_name:row.display_name,unit_price_minor:Math.round(price*100),minor,qty:quantity||1,unit_label:row.unit_label||'per install'});
}
const subtotal_minor = lines.reduce((a,l) => a + l.minor, 0);
const total_minor = subtotal_minor;
const price_ledger = lines.map(l => ({key:l.key,display_name:l.display_name,unit_price_minor:l.unit_price_minor,qty:l.qty,line_total_minor:l.minor,line_total_display:Math.floor(l.minor/100)+'.'+String(l.minor%100).padStart(2,'0')}));
const quote_rows_text = lines.map(l => l.display_name+': Â£'+(l.minor/100).toFixed(2)).join('\n');
const day = new Date().toISOString().split('T')[0];
const qid = 'Q-'+day+'-'+require('crypto').createHash('sha256').update(input.idempotency_key).digest('hex').slice(0,6).toUpperCase();
return [{json:{ok:true,quote_id:qid,quote_rows_text,subtotal_minor,total_minor,price_ledger,lines,contact_id:input.contact_id,contact_name:input.contact_name,email:input.email,company_name:input.company_name,currency:'GBP',services:lines.map(l=>({key:l.key,display_name:l.display_name}))}}];

const input = $json;
const ledger = input.price_ledger || [];
const allowed = new Set();
for (const item of ledger) {
  const m = (item.line_total_display||'').match(/\d+(?:\.\d+)?/g) || [];
  m.forEach(d => allowed.add(d));
}
let summaryText = null;
let summaryFailed = false;
if (input.data && input.data.text) {
  summaryText = input.data.text;
  const digits = summaryText.match(/\d+(?:\.\d+)?/g) || [];
  const hasBad = digits.some(d => !allowed.has(d)) || /Â£|GBP|%|TBD/.test(summaryText);
  if (hasBad) { summaryText = null; summaryFailed = true; }
} else { summaryFailed = true; }
return [{json:{...input,summary_text:summaryText,summary_failed:summaryFailed}}];

const input = $('Match + Price Quote').item.json;
const html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;"><h1>Quote from Solar London</h1><p>Reference: '+input.quote_id+'</p><table border="1" cellpadding="8"><tr><th>Service</th><th>Price</th></tr>'+input.price_ledger.map(l=>'<tr><td>'+l.display_name+'</td><td>'+l.line_total_display+'</td></tr>').join('')+'<tr style="font-weight:bold;"><td>Total</td><td>'+(input.total_display||'Â£0.00')+'</td></tr></table></div>';
const plain = 'Quote from Solar London - '+input.quote_id+'\n\n'+input.quote_rows_text+'\n\nTotal: '+(input.total_display||'Â£0.00');
const forbidden = ['{{','}}','[YOUR_','YOUR_GOOGLE','TBD','recipient@example.com','null','undefined','llama'];
const scan = html+' '+plain;
for (const p of forbidden) { if(scan.includes(p)) return [{json:{ok:false,needs_human:true,status:'failed_document',failure_reason:'unresolved_'+p}}]; }
return [{json:{...input,quote_email_html:html,quote_email_plain:plain,document_complete:true}}];

const input = $('Build Quote Document').item.json;
const required = ['ok','needs_human','status','quote_id','duplicate','contact_id','services','quote_rows_text','total_display','subtotal_minor','total_minor','currency','emailed','lead_line'];
for (const f of required) { if(input[f]===undefined) return [{json:{ok:false,needs_human:true,status:'contract_violation',failure_reason:'missing:'+f}}]; }
const allowed = new Set(required);
const extra = Object.keys(input).filter(k => !allowed.has(k) && !['data','json','item'].includes(k));
if(extra.length>0) return [{json:{ok:false,needs_human:true,status:'contract_violation',failure_reason:'extra_keys:'+extra.join(',')}}];
if(input.subtotal_minor !== input.total_minor) return [{json:{ok:false,needs_human:true,status:'contract_violation',failure_reason:'subtotal_mismatch'}}];
if(input.ok===true && input.emailed!==true) return [{json:{ok:false,needs_human:true,status:'contract_violation',failure_reason:'emailed_not_true'}}];
if(/\d/.test(String(input.lead_line||''))) return [{json:{ok:false,needs_human:true,status:'contract_violation',failure_reason:'digit_in_lead_line'}}];
const ledger = input.price_ledger||[];
const allowedNums = new Set();
for(const item of ledger){const m=(item.line_total_display||'').match(/\d+(?:\.\d+)?/g)||[];m.forEach(d=>allowedNums.add(d));}
for(const field of ['quote_rows_text','total_display','summary_text']){const v=input[field]||'';const d=v.match(/\d+(?:\.\d+)?/g)||[];for(const x of d){if(!allowedNums.has(x)) return [{json:{ok:false,needs_human:true,status:'contract_violation',failure_reason:'unverified_digit:'+x}}];}}
return [{json:{...input,contract_valid:true}}];
